from ship.rates import *


def shipping_fee(weight_kg, order_total):
    if order_total >= FREE_ABOVE:
        return 0.0
    fee = BASE + PER_KG * weight_kg
    if weight_kg > HEAVY_KG:
        fee += HEAVY_SURCHARGE
    return round(fee, 2)

